select lives_ok($$select public.capture_release_email_payload('89000000-0000-4000-8000-000000000004','88000000-0000-4000-8000-000000000001',(select v::text from data where k='payload'))$$,'Capture retry retains identical payload');
select throws_ok($$select public.capture_release_email_payload('89000000-0000-4000-8000-000000000004','88000000-0000-4000-8000-000000000001',(select (v||'{"text":"Changed"}')::text from data where k='payload'))$$,'23505',null,'Captured payload cannot change');
