-- Backdated operator fixture proves the bounded purge path without touching real records.
insert into public.release_email_requests(id,release_id,actor_id,conversation_id,client_id,recipient,subject,body,release_hash,state) select '89000000-0000-4000-8000-000000000010',release_id,actor_id,conversation_id,client_id,recipient,subject,body,release_hash,'abandoned' from public.release_email_requests where id='89000000-0000-4000-8000-000000000004';
insert into public.release_email_payloads(request_id,payload_text,payload_hash,manifest,captured_at) select '89000000-0000-4000-8000-000000000010',payload_text,payload_hash,manifest,now()-interval '91 days' from public.release_email_payloads where request_id='89000000-0000-4000-8000-000000000004';
set local role service_role;
select is(public.purge_expired_release_email_payloads(100),1,'Expired abandoned payload bytes are purged');
reset role;
select ok((select payload_text is null and purged_at is not null and jsonb_array_length(manifest)=2 and length(payload_hash)=64 from public.release_email_payloads where request_id='89000000-0000-4000-8000-000000000010'),'Purge preserves reviewed manifest and hash evidence');
reset role;set local role anon;
select throws_ok($$select public.recover_release_email('89000000-0000-4000-8000-000000000003')$$,'42501',null,'Anonymous recovery denied');
reset role;
select * from finish();rollback;
